@pytest.mark.parametrize('name',sorted(EXPECTED))
def test_page_content_forms_links_and_scripts_unchanged(name):
    assert signature((ROOT/name).read_text())==EXPECTED[name]

def test_home_base_and_original_branding_bytes_unchanged():
    for name,expected in PROTECTED.items():
        assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==expected,name

def test_polish_stylesheet_is_opt_in_only():
    linked={str(p.relative_to(ROOT)) for p in (ROOT/'templates').rglob('*.html') if 'css/public-page-polish.css' in p.read_text()}
    assert linked==set(EXPECTED)
    css=(ROOT/'static/css/public-page-polish.css').read_text()
    assert 'main.home' not in css and '#topBtn' not in css
    assert all('.public-page-polish' in line or 'confirm-email-polish' in line or 'forgot-password-polish' in line
               for line in css.splitlines() if '{' in line and not line.startswith('@'))

def test_routes_models_algorithms_and_analytics_unchanged():
    for name,expected in SERVICES.items():
        assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==expected,name
